export function dbfs(samples){let sum=0;for(const v of samples)sum+=v*v;const rms=Math.sqrt(sum/Math.max(1,samples.length));return rms>0?Math.max(-60,Math.min(0,20*Math.log10(rms))):-60;}
export function createAudioMeter(){
 let context=null,source=null,analyser=null,frame=null,lastDraw=0,shown=-60;
 const $=s=>document.querySelector(s);
 function draw(value,status){const bar=$('#micLevel');if(!bar)return;bar.value=value;bar.setAttribute('aria-valuetext',status);$('#micDb').textContent=value<=-60?'Below −60 dBFS':`${value.toFixed(1)} dBFS`;$('#micSignal').textContent=status;bar.className=value>-6?'loud':'';}
 function stop(){cancelAnimationFrame(frame);frame=null;source?.disconnect();source=null;const old=context;context=null;analyser=null;old?.close().catch(()=>{});shown=-60;if($('#micLevel')){$('#micLevel').value=-60;$('#micLevel').setAttribute('aria-valuetext','Microphone off');$('#micDb').textContent='— dBFS';$('#micSignal').textContent='Microphone off';}}
 async function start(stream){stop();const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext){if($('#micSignal'))$('#micSignal').textContent='Level meter unavailable in this browser';return;}try{context=new AudioContext();const active=context;source=context.createMediaStreamSource(stream);analyser=context.createAnalyser();analyser.fftSize=1024;source.connect(analyser);await context.resume();if(context!==active)return;const data=new Float32Array(analyser.fftSize);function tick(time){if(context!==active)return;analyser.getFloatTimeDomainData(data);const value=dbfs(data);shown=Math.max(value,shown-1.5);if(time-lastDraw>100){lastDraw=time;draw(shown,shown>-6?'Very loud — move back from the microphone':shown>-50?'Sound detected':'Quiet — speak to check the microphone');}frame=requestAnimationFrame(tick);}frame=requestAnimationFrame(tick);}catch{stop();if($('#micSignal'))$('#micSignal').textContent='Level meter unavailable; speech can still be used';}}
 return {start,stop};
}
